window.sfWeatherIconSvg = function(iconId, className = 'cal-weather-icon-img') {
    const inner = window.SF_WEATHER_ICONS[iconId] || '';
    const vb = window.SF_WEATHER_VIEWBOX[iconId] || '8 0 128 128';
    const str = `<svg class="${className}" viewBox="${vb}" fill="none" xmlns="http://www.w3.org/2000/svg">${inner}</svg>`;
    const parser = new DOMParser();
    const doc = parser.parseFromString(str, 'image/svg+xml');
    return doc.documentElement;
};
